 /* ================= v23.8.2: the start page opens at the start of every visit =================
    Returning visitors used to land straight in their last search (since 22.x), so the start page never appeared.
    Now it opens every time the site is opened or reloaded; the last search keeps loading behind it and
    "Continue with <place>" returns to it with one tap. Deep links (?lat=…, ?q=…, #place) open directly, as before. */
 (function(){var KEY='dm_start_seen';
  function deep(){return /[?&](lat|lon|q|name|spot|place)=/.test(location.search)||(location.hash&&location.hash.length>1&&!/^#(about|how)$/.test(location.hash))}
  function seen(){try{return sessionStorage.getItem(KEY)==='1'}catch(e){return true}}
  function mark(){try{sessionStorage.setItem(KEY,'1')}catch(e){}}
  function gate(){return document.querySelector('.gate')}
  function hidden(g){return !g||g.classList.contains('hidden')||getComputedStyle(g).display==='none'}
  function placeName(){try{var l=(typeof placeLabel==='function'?placeLabel():'')||state.label||'';return String(l).split(',')[0].replace(/ swim culture$/i,'').trim()}catch(e){return ''}}
  function addResume(g){var box=g.querySelector('.gateBox .actions');if(!box)return;var nm=placeName();var b=document.getElementById('dmGateResume');
   if(!nm||!state.center){if(b)b.remove();return}
   if(!b){b=document.createElement('button');b.type='button';b.id='dmGateResume';b.className='primary';box.insertBefore(b,box.firstChild);
    b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();var g2=gate();if(g2){g2.classList.add('hidden');g2.style.display='none'}try{scrollTo({top:0,behavior:'instant'})}catch(err){}})}
   b.textContent='Continue with '+nm}
  function open(){var g=gate();if(!g)return;if(!hidden(g)){mark();return}var br=document.querySelector('.topbar .brand');if(br){br.click()}else{g.classList.remove('hidden');g.style.display=''}addResume(g);mark()}
  var touched=false;['pointerdown','keydown','touchstart'].forEach(function(ev){addEventListener(ev,function(e){if(e.target&&e.target.closest&&e.target.closest('#dmBoot,#dmSplash'))return;touched=true},{capture:true,passive:true})});
  /* decided once, when the opening scene ends: a start page already on screen means a first visit (nothing to do);
     a hidden start page means the app restored the last search -> open the start page over it, unless the visitor is already busy */
  function go(){mark(); /* The selected map stays visible. The logo still opens destination search. */}
  if(window.__dmBootDone)setTimeout(go,50);else document.addEventListener('dmbootdone',function(){setTimeout(go,50)});
  /* keep the resume button in step whenever the start page is opened from the logo */
  document.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('.topbar .brand'))setTimeout(function(){var g=gate();if(g&&!hidden(g))addResume(g)},60)},true);
 })();


 /* v23.7: specials with an approximate position are placed exactly in the background, one lookup every 1.2 s (Nominatim policy), and remembered */
 var GEOQ=[],GEOT=null;function geoQueue(L){L.forEach(function(v){if(GEOQ.indexOf(v)<0)GEOQ.push(v)});if(GEOT)return;var step=function(){var v=GEOQ.shift();if(!v){GEOT=null;return}if(v.geo==='approx')refineGeo(v);GEOT=setTimeout(step,1200)};GEOT=setTimeout(step,800)}
 function refineGeo(v){if(!v.addr||typeof fetchJsonTimeout!=='function')return;var q='https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(v.addr);
  fetchJsonTimeout(q,{},8000).then(function(r){var h=r&&r[0];if(!h)return;var la=+h.lat,lo=+h.lon;if(!isFinite(la)||D(la,lo,v.lat,v.lon)>(v.ev==='sp'?25:5))return;GEO[v.dirId]=[la,lo];try{localStorage.setItem('dm_geo_v1',JSON.stringify(GEO))}catch(e){}
   v.lat=la;v.lon=lo;v.geo='refined';if(state.center)v.dist=D(state.center[0],state.center[1],la,lo);paint(true)}).catch(function(){})}
